'use client'
import { ChevronDown } from 'lucide-react'
import { useEffect, useId, useRef, useState, type CSSProperties, type ReactNode } from 'react'
import { AnswerText } from '@/components/product/AnswerText'
import { DownloadButton } from '@/components/product/DownloadButton'
import { PagePreview } from '@/components/product/PagePreview'
import { DotMatrix } from '@/components/ui/DotMatrix'
import { MarkedText } from '@/components/ui/MarkedText'
import { resultKey, type ResultPage, type SearchResult } from '@/hooks/useSearchResults'
import { cn } from '@/lib/cn'

// Search results, "Best match" (search/BestMatch.vue): the top result is the answer most of the time, so it gets the
// card, the full passage at a larger size with the query's words marked, the pages around it (its own outlined in red)
// and its source; the rest follow as one quiet line each, to scan, and a line opens in place to its full passage.
// `answer` puts a written answer in the card instead of the passage, citing results [1], [2]; `writing` holds the
// card's room with the dot matrix while it is written. `reveal` (a result's key and a time) opens that result, brings
// it into view and flashes it once, as the search run's squares do. `logoOf` gives a namespace's app mark. `download`
// puts the document's dark Download button (document-download) under the best match and each opened match, keyed by
// the result's key so it says Downloaded once it has; `actions` (Vue's scoped slot, a function of the result) adds
// other buttons beside it. Results rise in, 60ms apart.
export interface SearchResultsProps {
  results: SearchResult[]
  query: string
  answer?: string
  writing?: boolean
  reveal?: { key: string, at: number } | null
  logoOf?: (namespace: string) => string | null | undefined
  download?: (result: SearchResult) => void
  onCite?: (key: string) => void
  actions?: (result: SearchResult) => ReactNode
}

const pageLine = (p: ResultPage) => `Page ${p.number} of ${p.count}`
// The pages before and after the passage's, unmarked.
const around = (p: ResultPage) => [p.number - 1, p.number, p.number + 1].filter(n => n >= 1 && n <= p.count).map(n => ({ ...p, number: n, here: n === p.number }))

export function SearchResults({ results, query, answer, writing, reveal, logoOf, download, onCite, actions }: SearchResultsProps) {
  const pre = `match-${useId()}`
  const [open, setOpen] = useState('')
  useEffect(() => setOpen(''), [results])
  const logo = (ns: string) => logoOf?.(ns) ?? null
  const answers = writing || answer !== undefined

  // A flash clears, then comes back once the page has drawn without it (Vue's nextTick), so its animation runs again.
  const [flash, setFlash] = useState('')
  const pending = useRef<{ key: string, i: number } | null>(null)
  function bringIn(key: string) {
    const i = results.findIndex(r => resultKey(r) === key)
    if (i < 0) return
    if (i > 0) setOpen(key)
    setFlash('')
    pending.current = { key, i }
  }
  useEffect(() => {
    const p = pending.current
    if (!p || flash) return
    pending.current = null
    setFlash(p.key)
    document.getElementById(p.i === 0 ? `${pre}-top` : `${pre}-row-${p.i - 1}`)?.scrollIntoView({ behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'center' })
  })
  useEffect(() => { if (reveal) bringIn(reveal.key) }, [reveal?.at]) // eslint-disable-line react-hooks/exhaustive-deps
  function cite(n: number) {
    const r = results[n - 1]
    if (!r) return
    onCite?.(resultKey(r))
    bringIn(resultKey(r))
  }
  const ends = (r: SearchResult) => (actions || download) && <span className="flex items-center gap-2">{actions?.(r)}{download && <DownloadButton id={resultKey(r)} onPress={() => download(r)} />}</span>

  const top = results[0]
  return (
    <div data-ds="search-results" className="ds-results flex flex-col gap-6">
      <style href="ds-search-results" precedence="ds">{css}</style>
      {top && (
        <article id={`${pre}-top`} className="ds-rise border border-edge bg-surface" data-flash={flash === resultKey(top) || undefined} style={{ '--i': 0 } as CSSProperties}>
          <div className="flex min-w-0 flex-col gap-9 px-4 pt-4 pb-4.5">
            {answers
              ? (
                  <div className="min-h-12" aria-live="polite">
                    {writing
                      ? <p className="inline-flex items-center gap-1.5 type-meta"><DotMatrix />Writing an answer</p>
                      : answer ? <AnswerText text={answer} onCite={cite} /> : <p className="ds-answer-text"><MarkedText text={top.text} query={query} /></p>}
                  </div>
                )
              : <p className="type-body-lg text-ds-neutral-200"><MarkedText text={top.text} query={query} /></p>}
            {top.page && (
              <div className="flex items-end gap-2">
                {around(top.page).map(p => <PagePreview key={p.number} page={p} size="thumb" marked={p.here} here={p.here} />)}
                <span className="ml-1 type-meta text-fg-muted">{`${pageLine(top.page)} in `}<span className="type-code-sm">{top.page.file}</span></span>
              </div>
            )}
          </div>
          <div className="flex flex-wrap items-center justify-between gap-3 border-t border-edge py-2.5 pr-2 pl-4">
            <span className="flex min-w-0 items-center gap-1.5">
              {logo(top.namespace) && <img src={logo(top.namespace)!} alt="" width="14" height="14" className="size-3.5 shrink-0 object-contain" />}
              <span className="truncate type-code-sm">{top.id}</span>
              <span className="shrink-0 type-meta text-fg-muted">in <span className="type-code-sm">{top.namespace}</span>{`, ${top.score.toFixed(2)}`}</span>
            </span>
            {ends(top)}
          </div>
        </article>
      )}

      {results.length > 1 && (
        <section className="ds-others flex flex-col gap-1" aria-labelledby={`${pre}-more`}>
          <h2 id={`${pre}-more`} className="type-meta text-fg-muted">Other matches</h2>
          <ol className="ds-others-rows">
            {results.slice(1).map((r, i) => {
              const key = resultKey(r)
              const on = open === key
              return (
                <li id={`${pre}-row-${i}`} key={key} className="ds-rise" data-flash={flash === key || undefined} style={{ '--i': i + 1 } as CSSProperties}>
                  <button type="button" className="ds-match w-full text-left" aria-expanded={on} aria-controls={`${pre}-${i}`} onClick={() => setOpen(o => (o === key ? '' : key))}>
                    {logo(r.namespace) && <img src={logo(r.namespace)!} alt="" width="12" height="12" className="size-3 shrink-0 object-contain" />}
                    <span className="ds-match-id w-40 shrink-0 truncate max-sm:w-auto max-sm:min-w-0 max-sm:flex-1">{r.id}</span>
                    <span className={cn('hidden min-w-0 flex-1 truncate sm:block', on && 'invisible')}>{r.text}</span>
                    {r.page && <span className="hidden shrink-0 tabular-nums sm:inline">{`p. ${r.page.number}`}</span>}
                    <span className="shrink-0 tabular-nums">{r.score.toFixed(2)}</span>
                    <ChevronDown size={12} strokeWidth={1.5} className="ds-match-chev shrink-0 text-fg-muted" aria-hidden="true" />
                  </button>
                  {/* Opens by its rows' height (0fr to 1fr), so it grows to fit. */}
                  <div id={`${pre}-${i}`} className="ds-expand" data-open={on || undefined} inert={!on}>
                    <div className="min-h-0 overflow-hidden">
                      <div className="flex min-w-0 flex-col gap-3 pt-1 pb-3">
                        <p className="leading-5.5 text-ds-neutral-200"><MarkedText text={r.text} query={query} /></p>
                        <div className="flex flex-wrap items-center justify-between gap-3">
                          <span className="flex flex-wrap gap-x-4 gap-y-1 type-meta text-fg-muted">
                            <span>in <span className="type-code-sm">{r.namespace}</span></span>
                            {r.page && <span>{pageLine(r.page)}</span>}
                          </span>
                          {ends(r)}
                        </div>
                      </div>
                    </div>
                  </div>
                </li>
              )
            })}
          </ol>
        </section>
      )}
    </div>
  )
}

export default SearchResults

const css = `
/* Results rise in, each 60ms after the last (console2.css .v2-results[data-motion="1"] .v2-rise). */
.ds-results .ds-rise { animation: ds-results-in var(--ds-duration-enter) var(--ds-easing-out) both; animation-delay: calc(var(--i, 0) * 60ms); }
@keyframes ds-results-in { from { opacity: 0; transform: translateY(12px); } }
/* The dot matrix in red while the answer is written (.v2-proc .v2-matrix). */
.ds-results .ds-matrix i { background: var(--ds-color-edge-accent); }
.ds-others-rows > * + * { border-top: var(--ds-border-hairline) solid var(--ds-color-edge); }
/* Other matches: a quiet list under the answer, every row still opening. */
.ds-match { display: flex; min-height: var(--ds-size-control-md); align-items: center; gap: var(--ds-space-md); padding: 0; color: var(--ds-color-fg-muted); font-size: var(--ds-text-meta); line-height: var(--ds-text-meta-leading); transition: color var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-match-id { color: var(--ds-color-fg-soft); font-family: var(--ds-font-code); font-size: var(--ds-text-meta); transition: color var(--ds-duration-micro) var(--ds-easing-standard); }
@media (hover: hover) and (pointer: fine) {
  .ds-match:hover { color: var(--ds-color-fg-soft); }
  .ds-match:hover .ds-match-id { color: var(--ds-color-fg); }
}
.ds-match:focus-visible { outline: var(--ds-border-focus) solid var(--ds-color-edge-accent); outline-offset: -2px; }
.ds-match-chev { transition: rotate var(--ds-duration-micro) var(--ds-easing-out); }
.ds-match[aria-expanded="true"] .ds-match-chev { rotate: 180deg; transition-duration: var(--ds-duration-slide); }
.ds-expand { display: grid; grid-template-rows: 0fr; transition: grid-template-rows var(--ds-duration-slide) var(--ds-easing-out); }
.ds-expand[data-open] { grid-template-rows: 1fr; }
/* A result shown from its square flashes its red outline once. */
.ds-results [data-flash] { animation: ds-results-flash var(--ds-duration-flash) var(--ds-easing-standard) both; }
@keyframes ds-results-flash { 0%, 40% { outline: var(--ds-border-focus) solid var(--ds-color-edge-accent); outline-offset: -2px; } 100% { outline: var(--ds-border-focus) solid transparent; outline-offset: -2px; } }
@media (prefers-reduced-motion: reduce) {
  .ds-results .ds-rise, .ds-results [data-flash] { animation: none; }
  .ds-match-chev, .ds-expand { transition: none; }
}
`

import { Fragment } from 'react'
import { citeParts } from '@/hooks/useSearchResults'

// A written answer's words at 16px with its sources as small ink squares, [1] and [2] in the text becoming numbered
// buttons (console2.css .v2-written-text, .v2-cite). A citation turns red under the pointer and while it is the one
// shown (`pointed`). The words rise in once, a blur clearing (.v2-answer-in).
export interface AnswerTextProps {
  text: string
  pointed?: number
  onCite?: (n: number) => void
  onPoint?: (n: number) => void
}

export function AnswerText({ text, pointed, onCite, onPoint }: AnswerTextProps) {
  return (
    <p data-ds="answer-text" className="ds-answer-text">
      <style href="ds-answer-text" precedence="ds">{css}</style>
      {citeParts(text).map((p, i) => ('cite' in p
        ? <button key={i} type="button" className="ds-cite" aria-label={`Source ${p.cite}`} aria-pressed={pointed === undefined ? undefined : pointed === p.cite} onPointerEnter={() => onPoint?.(p.cite)} onFocus={() => onPoint?.(p.cite)} onClick={() => onCite?.(p.cite)}>{p.cite}</button>
        : <Fragment key={i}>{p.words}</Fragment>))}
    </p>
  )
}

export default AnswerText

const css = `
.ds-answer-text { margin: 0; font-size: var(--ds-text-input); line-height: var(--ds-text-input-leading); animation: ds-answer-in var(--ds-duration-rise) var(--ds-easing-out) both; }
@keyframes ds-answer-in { from { opacity: 0; filter: blur(2px); transform: translateY(4px); } }
.ds-cite { position: relative; display: inline-flex; min-width: 16px; height: 16px; align-items: center; justify-content: center; margin-inline: 2px; background: var(--ds-color-fg); color: var(--ds-color-fg-inverse); font-size: var(--ds-text-meta); line-height: 16px; vertical-align: 2px; font-variant-numeric: tabular-nums; transition: background-color var(--ds-duration-micro) var(--ds-easing-standard); touch-action: manipulation; }
/* Small to the eye, larger to the pointer: 24px, 40px on touch. */
.ds-cite::after { position: absolute; inset: -4px; content: ""; }
.ds-cite[aria-pressed="true"] { background: var(--ds-color-home-red-press); }
@media (hover: hover) and (pointer: fine) { .ds-cite:hover { background: var(--ds-color-home-red-press); } }
.ds-cite:focus-visible { outline: var(--ds-border-focus) solid var(--ds-color-edge-accent); outline-offset: 2px; }
@media (pointer: coarse) { .ds-cite::after { inset: -12px; } }
@media (prefers-reduced-motion: reduce) { .ds-answer-text { animation-name: ds-answer-fade; } }
@keyframes ds-answer-fade { from { opacity: 0; } }
`

import { Fragment } from 'react'
import { MarkedText } from '@/components/ui/MarkedText'
import type { ResultPage } from '@/hooks/useSearchResults'

// A document's page drawn small, with the passage marked where it sits on it (search/PagePreview.vue). A result
// carries only its passage, so the page's other lines are drawn as rules: at thumb and mid size the passage is a band
// of darker rules on the red tint with a red edge; at full size it is its own words, the query's in medium weight.
// Thumb and mid are pictures (say the page number beside them); full is read.
export interface PagePreviewProps {
  page: ResultPage
  text?: string
  query?: string
  size?: 'thumb' | 'mid' | 'full'
  marked?: boolean
  here?: boolean
}

const COUNT = { thumb: 11, mid: 22, full: 26 }
// Line lengths in percent; 0 is the gap between paragraphs.
const WIDTHS = [100, 97, 99, 94, 100, 62, 0, 98, 100, 95, 100, 71, 0]

export function PagePreview({ page, text = '', query = '', size = 'mid', marked = true, here }: PagePreviewProps) {
  const band = size === 'thumb' ? 2 : 4
  const n = COUNT[size]
  const at = Math.min(n - 3, Math.round(page.top * n))
  const span = size === 'thumb' ? 2 : size === 'mid' ? 4 : 1
  const lines = Array.from({ length: n }, (_, i) => ({ w: WIDTHS[(i + page.number * 3) % WIDTHS.length]!, hit: marked && i >= at && i < at + span, first: i === at }))
  return (
    <div data-ds="page-preview" className="ds-pg" data-size={size} data-here={here || undefined} aria-hidden={size === 'full' ? undefined : 'true'}>
      <style href="ds-page-preview" precedence="ds">{css}</style>
      <span className="ds-pg-head" />
      {lines.map((l, i) => (
        <Fragment key={i}>
          {size === 'full' && l.first
            ? <p className="ds-pg-hit ds-pg-words"><MarkedText text={text} query={query} /></p>
            : l.hit && size !== 'full' && l.first
              ? <span className="ds-pg-hit">{Array.from({ length: band }, (_, k) => <span key={k} className="ds-pg-line" style={{ width: k + 1 === band ? '68%' : '100%' }} />)}</span>
              : !l.hit ? <span className="ds-pg-line" style={{ width: `${l.w}%` }} data-gap={l.w === 0 || undefined} /> : null}
        </Fragment>
      ))}
      {size !== 'thumb' && <span className="ds-pg-foot">{page.number}</span>}
    </div>
  )
}

export default PagePreview

const css = `
.ds-pg { position: relative; display: flex; flex-shrink: 0; flex-direction: column; overflow: hidden; border: var(--ds-border-hairline) solid var(--ds-color-edge); background: var(--ds-color-surface); }
.ds-pg-line { display: block; height: 1px; flex-shrink: 0; background: var(--ds-color-edge-strong); opacity: 0.55; }
.ds-pg-line[data-gap] { opacity: 0; }
.ds-pg-head { display: block; width: 34%; height: 1px; flex-shrink: 0; background: var(--ds-color-edge-strong); }
.ds-pg-hit { display: flex; flex-shrink: 0; flex-direction: column; background: linear-gradient(var(--ds-color-edge-accent), var(--ds-color-edge-accent)) left / 2px 100% no-repeat, color-mix(in srgb, var(--ds-color-edge-accent) 14%, transparent); }
.ds-pg-hit .ds-pg-line { background: var(--ds-color-off-black); opacity: 0.8; }
/* ds-override: the folio of a drawn page, 8px as the branch draws it, not a text size */
.ds-pg-foot { position: absolute; right: 0; bottom: 6px; left: 0; color: var(--ds-color-fg-muted); font-size: 8px; line-height: 8px; text-align: center; font-variant-numeric: tabular-nums; }
.ds-pg[data-size="thumb"] { width: 28px; height: 36px; gap: 2px; padding: 4px 4px; }
.ds-pg[data-size="thumb"] .ds-pg-head { margin-bottom: 1px; }
.ds-pg[data-size="thumb"] .ds-pg-hit { gap: 2px; margin: 0 -2px; padding: 1px 2px; }
.ds-pg[data-size="mid"] { width: 152px; height: 197px; gap: 4px; padding: 14px 14px 22px; }
.ds-pg[data-size="mid"] .ds-pg-line { height: 2px; }
.ds-pg[data-size="mid"] .ds-pg-head { height: 2px; margin-bottom: 6px; }
/* ds-override: the band reaches 3px past the page's rules, as the branch draws it */
.ds-pg[data-size="mid"] .ds-pg-hit { gap: 4px; margin: -1px -4px; padding: 3px 4px; }
.ds-pg[data-size="mid"] .ds-pg-hit .ds-pg-line { height: 2px; }
.ds-pg[data-size="full"] { width: 100%; gap: 12px; padding: 40px 40px 56px; }
.ds-pg[data-size="full"] .ds-pg-line { height: 5px; }
.ds-pg[data-size="full"] .ds-pg-line[data-gap] { height: 2px; }
.ds-pg[data-size="full"] .ds-pg-head { height: 5px; margin-bottom: 12px; }
.ds-pg[data-size="full"] .ds-pg-foot { bottom: 20px; font-size: var(--ds-text-caption); line-height: 12px; }
.ds-pg-words { margin: 2px -8px; padding: 8px; color: var(--ds-color-fg); font-size: var(--ds-text-ui); line-height: var(--ds-text-ui-leading); }
.ds-pg[data-here] { outline: var(--ds-border-hairline) solid var(--ds-color-edge-accent); outline-offset: 2px; }
@media (max-width: 639px) { .ds-pg[data-size="full"] { padding: 28px 24px 48px; } }
`

// What the search's parts share (SearchResults, SearchRun, WrittenAnswer): the result's shape and a written answer
// split at its citations. The query's words are marked by MarkedText.

/** The page a passage stands on, for results from PDF and Word documents: `top` is where on the page (0 to 1). */
export type ResultPage = { number: number, count: number, top: number, file: string }

/** One passage a search found. */
export type SearchResult = { namespace: string, id: string, score: number, text: string, page?: ResultPage }

/** A written answer that marks its sources [1], [2], as words and citation numbers. */
export function citeParts(text: string): Array<{ words: string } | { cite: number }> {
  return text.split(/(\[\d+\])/).filter(Boolean).map(p => (/^\[\d+\]$/.test(p) ? { cite: Number(p.slice(1, -1)) } : { words: p }))
}

/** A result's key, unique across namespaces. */
export const resultKey = (r: SearchResult) => `${r.namespace}/${r.id}`

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
